mapper.select:
SELECT p.id, p.grade_code, g.name AS grade_name, p.rebate_rate, p.valid_from, p.valid_to, CASE WHEN p.valid_from > #{today} THEN 'SCHEDULED' WHEN p.valid_to IS NOT NULL AND p.valid_to <= #{today} THEN 'ENDED' ELSE 'CURRENT' END AS state FROM rebate_policy p JOIN partner_grade g ON g.grade_code = p.grade_code
p.grade_code = #{gradeCode}
ORDER BY p.grade_code, p.valid_from DESC
